const config = {
  "previewFeatures": [],
  "clientVersion": "7.9.1",
  "engineVersion": "e922089b7d7502aff4249d5da3420f6fa55fc6ad",
  "activeProvider": "postgresql",
  "inlineSchema": "// Phase 1 schema — identity, tenancy, and university configuration only.\n// No activity/schedule/deliverable models yet (Phases 2-4).\n\ngenerator client {\n  provider = \"prisma-client-js\"\n  output   = \"../src/generated/prisma\"\n}\n\n// Prisma 7: the connection URL lives in prisma.config.ts (CLI) and is supplied\n// to PrismaClient at runtime via the pg adapter in src/server/db.ts.\ndatasource db {\n  provider = \"postgresql\"\n}\n\nenum Role {\n  ADMIN\n  MANAGER\n  INSTRUCTOR\n}\n\nenum ActivityStatus {\n  COMPLETED\n  MISSED\n  LATE\n  EXCUSED\n}\n\n/// The sole identity + auth record (Phase 0 §3.1).\n/// `universityId` is the AUTHORITATIVE tenant binding used by the auth layer.\n/// It is null for ADMIN and only for ADMIN — enforced by a CHECK constraint\n/// added in migration `phase1_invariants`.\nmodel User {\n  id           String  @id @default(cuid())\n  email        String  @unique\n  passwordHash String\n  name         String\n  role         Role\n  isActive     Boolean @default(true)\n\n  phone       String?\n  /// The user's own profile picture, held as a size-capped `data:` URI.\n  ///\n  /// A column rather than a file because this application has no object storage\n  /// and deliberately writes no uploads to disk — the bulk importer drops the\n  /// files it reads for the same reason. An avatar is small and is read only by\n  /// the profile endpoints, never by session validation, so the cost stays where\n  /// it belongs. The endpoint enforces the image type and the size cap; nothing\n  /// else in the application writes this field.\n  avatarUrl   String?\n  lastLoginAt DateTime?\n\n  /// When this person left. Soft delete: someone leaving must not erase their\n  /// recorded work. Set together with `isActive: false`, cleared if they are\n  /// ever reinstated.\n  ///\n  /// `isActive` alone answered \"can they sign in\", which is the security\n  /// question, and left the OPERATIONAL one — who left, and when — recoverable\n  /// only by reading the audit log. A company keeps a leavers list; this is the\n  /// column that makes one queryable.\n  deletedAt DateTime?\n\n  /// Why they left, in the operator's own words. Never a credential, and never\n  /// a judgement the system invented — it is typed by whoever processes the exit.\n  leftReason String?\n\n  universityId String?\n  university   University? @relation(\"UniversityUsers\", fields: [universityId], references: [id], onDelete: Restrict)\n\n  managerProfile    Manager?\n  instructorProfile Instructor?\n  sessions          Session[]\n  auditLogs         AuditLog[]\n  notifications     Notification[]\n\n  createdAt        DateTime            @default(now())\n  updatedAt        DateTime            @updatedAt\n  reportJobs       ReportJob[]\n  importJobs       ImportJob[]         @relation(\"ImportJobCreatedBy\")\n  worklogDecisions WorklogSubmission[] @relation(\"WorklogDecidedBy\")\n\n  /// Records this user authored on someone else's behalf (§14 created_by).\n  activityLogsCreated ActivityLog[] @relation(\"ActivityCreatedBy\")\n  deliverablesCreated Deliverable[] @relation(\"DeliverableCreatedBy\")\n\n  // Target of the composite FKs on Manager/Instructor. This is what makes it\n  // structurally impossible for a profile to sit in a different university\n  // than its own user account.\n  @@unique([id, universityId])\n  @@index([universityId])\n  /// The leavers list is a filter on this, so it should not be a table scan.\n  @@index([deletedAt])\n}\n\nmodel University {\n  id   String @id @default(cuid())\n  name String\n  slug String @unique\n\n  /// Human-facing tenant code (e.g. UNIV001). Unique platform-wide because it\n  /// is used in exports and support conversations.\n  code         String           @unique\n  status       UniversityStatus @default(ACTIVE)\n  country      String?\n  state        String?\n  city         String?\n  contactEmail String?\n  contactPhone String?\n\n  /// Soft delete (§36): universities own historical workforce records, so a\n  /// hard delete would destroy audit history. Nothing cascades from here.\n  deletedAt DateTime?\n  /// IANA timezone (e.g. \"Asia/Kolkata\"). Every \"working day\" boundary for this\n  /// tenant is computed in this zone, never the server's or browser's (§3.3).\n  timezone  String\n\n  /// Configurable per university, defaults per the core business rule.\n  openingDurationMin Int @default(15)\n  closingDurationMin Int @default(15)\n\n  /// Non-working break time inside the working day (e.g. lunch). Subtracted\n  /// from available capacity, per the utilisation formula. Defaults to 0 so no\n  /// break is ever assumed silently — each university configures its own.\n  breakDurationMin Int @default(0)\n\n  /// v1: one primary manager per university (§3.7). Nullable so a university can\n  /// exist before its manager is provisioned; modelled as an FK rather than a\n  /// flag on Manager so multi-manager support later needs no column split.\n  primaryManagerId String?  @unique\n  primaryManager   Manager? @relation(\"PrimaryManager\", fields: [primaryManagerId], references: [id], onDelete: SetNull)\n\n  users              User[]                   @relation(\"UniversityUsers\")\n  managers           Manager[]                @relation(\"UniversityManagers\")\n  instructors        Instructor[]             @relation(\"UniversityInstructors\")\n  workingHours       UniversityWorkingHours[]\n  holidays           UniversityHoliday[]\n  leaveRequests      LeaveRequest[]\n  activityLogs       ActivityLog[]\n  deliverables       Deliverable[]\n  aiInsights         AiInsight[]\n  auditLogs          AuditLog[]\n  worklogSubmissions WorklogSubmission[]\n\n  createdAt               DateTime                 @default(now())\n  updatedAt               DateTime                 @updatedAt\n  notifications           Notification[]\n  universitySettings      UniversitySettings?\n  departments             Department[]\n  programs                Program[]\n  academicTerms           AcademicTerm[]\n  courses                 Course[]\n  courseAssignments       CourseAssignment[]\n  schedules               Schedule[]\n  scheduleSlots           ScheduleSlot[]\n  breakPolicies           BreakPolicy[]\n  workloadTargets         WorkloadTarget[]\n  reportingPeriods        ReportingPeriod[]\n  instructorDailyMetrics  InstructorDailyMetric[]\n  instructorWeeklyMetrics InstructorWeeklyMetric[]\n  universityDailyMetrics  UniversityDailyMetric[]\n  reportJobs              ReportJob[]\n  deliverableLogs         DeliverableLog[]\n\n  worklogDaySummaries WorklogDaySummary[]\n\n  /// One row per day. See `WorklogEntry`.\n  worklogEntries WorklogEntry[]\n}\n\n/// One row per weekday per university. Times are minutes-from-midnight in the\n/// university's own timezone — storing a TIME or DateTime here would silently\n/// re-introduce a server-timezone dependency.\nmodel UniversityWorkingHours {\n  id           String     @id @default(cuid())\n  universityId String\n  university   University @relation(fields: [universityId], references: [id], onDelete: Cascade)\n\n  /// 0 = Sunday … 6 = Saturday\n  dayOfWeek    Int\n  isWorkingDay Boolean @default(true)\n  startMinute  Int\n  endMinute    Int\n\n  @@unique([universityId, dayOfWeek])\n}\n\nmodel UniversityHoliday {\n  id           String     @id @default(cuid())\n  universityId String\n  university   University @relation(fields: [universityId], references: [id], onDelete: Cascade)\n\n  /// A calendar date in the university's timezone — deliberately DATE, not\n  /// timestamptz, because a holiday is a local-calendar concept.\n  date DateTime @db.Date\n  name String\n\n  @@unique([universityId, date])\n}\n\nmodel Manager {\n  id           String @id @default(cuid())\n  userId       String @unique\n  universityId String\n\n  // Composite FK: (userId, universityId) must match an existing (User.id,\n  // User.universityId) pair. Guarantees profile.universityId can never drift\n  // from the authoritative user.universityId.\n  user       User       @relation(fields: [userId, universityId], references: [id, universityId], onDelete: Cascade)\n  university University @relation(\"UniversityManagers\", fields: [universityId], references: [id], onDelete: Restrict)\n\n  primaryOf University? @relation(\"PrimaryManager\")\n\n  employeeCode String?\n  createdAt    DateTime    @default(now())\n  updatedAt    DateTime    @updatedAt\n  aiInsights   AiInsight[]\n\n  /// The instructors this manager leads. A manager owns a roster, not the whole\n  /// university: two managers in one tenant have different people reporting to\n  /// them, which is the distinction the university-level scope cannot express.\n  instructors Instructor[] @relation(\"ManagerInstructors\")\n\n  // Required by Prisma for the composite FK above; userId alone is already\n  // unique, so this adds no new business constraint.\n  @@unique([userId, universityId])\n  @@unique([universityId, employeeCode])\n  // Target for Instructor's composite (managerId, universityId) FK. `id` is\n  // already the primary key, so this adds no business constraint either — it\n  // exists so the database can enforce that a manager and the instructors\n  // reporting to them are always in the same university.\n  @@unique([id, universityId])\n  @@index([universityId])\n}\n\n/// The instructor's own note about a day: \"all planned sessions completed\",\n/// \"lab ran short, two students to follow up\".\n///\n/// ── Why this is not the activity remarks joined together ──────────────────\n/// Those are read out of the sentences and describe individual entries — a\n/// topic, a batch, a unit. This is a judgement about the DAY as a whole, and\n/// only the person who lived it can make it. The client's report has a column\n/// for exactly this, and filling it by concatenating topics would put \"binary\n/// trees, section A\" where \"all planned sessions completed\" belongs.\n///\n/// One per instructor per day, so writing it again is a correction rather than\n/// a second opinion.\nmodel WorklogDayNote {\n  id String @id @default(cuid())\n\n  instructorId String\n  instructor   Instructor @relation(fields: [instructorId], references: [id], onDelete: Cascade)\n\n  universityId String\n  /// The day being described, in the university's zone.\n  workDate     DateTime @db.Date\n\n  note String\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@unique([instructorId, workDate])\n  @@index([universityId, workDate])\n}\n\n/// What an instructor TEACHES: Technical, English, Aptitude or Mathematics.\n///\n/// ── It is a specialism, not a department ──────────────────────────────────\n/// Somebody from any tech discipline delivering programming is TECH; the column\n/// says what they teach, not which department they came from. Confirmed against\n/// the client's own roster: TECH instructors sit against Programming\n/// Foundations, Python, Node JS, DSA and React; ENGLISH against Communicative\n/// English Foundation and Advanced; APTITUDE against Logical Reasoning and\n/// Quantitative Aptitude; MATH against Numerical Ability and Probability &\n/// Statistics. Four categories, ~600 instructors, and the split is clean.\n///\n/// ── Why it cannot be derived, and must be set ─────────────────────────────\n/// The obvious shortcut is to read somebody's courses and infer their stream.\n/// The data says no: below the top few courses the associations overlap heavily\n/// — ENGLISH instructors are attached to \"Build Your Own Static Website\",\n/// MATH instructors to \"Generative AI\" — because an instructor is linked to the\n/// whole programme their students take, not only what they personally deliver.\n/// Any inference from activity would therefore be wrong for a large minority,\n/// and wrong differently each month: somebody who spent a month on meetings\n/// would change category, and a signed-off sheet would reshuffle its own rows\n/// between two readings of the same period. Somebody is hired into a stream and\n/// stays in it, so an admin sets it and it stays set.\n///\n/// Held as a TABLE rather than an enum for the same reason the activity\n/// taxonomy is: adding \"Data Science\" should be an insert and a seed run, not\n/// a migration and a deploy.\nmodel InstructorCategory {\n  id    String @id @default(cuid())\n  code  String @unique\n  label String\n\n  sortOrder Int     @default(100)\n  isActive  Boolean @default(true)\n\n  instructors  Instructor[]\n  activityLogs ActivityLog[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([sortOrder])\n}\n\nmodel Instructor {\n  id           String @id @default(cuid())\n  userId       String @unique\n  universityId String\n\n  /// Nullable because it is ASSIGNED, never inferred — an instructor nobody has\n  /// categorised yet is a real state, and the sheet shows it as blank rather\n  /// than guessing. `Restrict`, so a category in use cannot be deleted out from\n  /// under the rows that report on it.\n  categoryId String?\n  category   InstructorCategory? @relation(fields: [categoryId], references: [id], onDelete: Restrict)\n\n  user       User       @relation(fields: [userId, universityId], references: [id, universityId], onDelete: Cascade)\n  university University @relation(\"UniversityInstructors\", fields: [universityId], references: [id], onDelete: Restrict)\n\n  /// Who this instructor reports to. Nullable because ownership is assigned by\n  /// an admin, never inferred: an instructor who has not been placed on a\n  /// roster yet is \"unassigned\", which is a real state and not a defect.\n  ///\n  /// The FK is COMPOSITE — (managerId, universityId) against Manager's\n  /// (id, universityId) — so PostgreSQL itself refuses an instructor whose\n  /// manager belongs to another university. That is the same technique the\n  /// User relation above uses, and it means cross-tenant assignment is\n  /// impossible rather than merely guarded against in application code.\n  ///\n  /// Restrict, not SetNull: on a composite FK, SET NULL would null BOTH\n  /// columns, and universityId is NOT NULL. Managers are deactivated rather\n  /// than deleted, so nothing legitimate is blocked.\n  managerId String?\n  manager   Manager? @relation(\"ManagerInstructors\", fields: [managerId, universityId], references: [id, universityId], onDelete: Restrict)\n\n  employeeCode            String?\n  activityLogs            ActivityLog[]\n  deliverables            Deliverable[]\n  leaveRequests           LeaveRequest[]\n  createdAt               DateTime                 @default(now())\n  updatedAt               DateTime                 @updatedAt\n  aiInsights              AiInsight[]\n  courseAssignments       CourseAssignment[]\n  schedules               Schedule[]\n  scheduleSlots           ScheduleSlot[]\n  workloadTargets         WorkloadTarget[]\n  deliverableLogs         DeliverableLog[]\n  instructorDailyMetrics  InstructorDailyMetric[]\n  instructorWeeklyMetrics InstructorWeeklyMetric[]\n  worklogDayNotes         WorklogDayNote[]\n\n  worklogSubmissions WorklogSubmission[]\n\n  worklogDaySummaries WorklogDaySummary[]\n\n  /// Cached AI insights for this instructor's periods. See `AiInsightCache`.\n  insightCaches AiInsightCache[]\n\n  /// One row per day. See `WorklogEntry`.\n  worklogEntries WorklogEntry[]\n\n  /// Parsed structure per day. See `DayExtraction`.\n  dayExtractions DayExtraction[]\n\n  @@unique([userId, universityId])\n  @@unique([universityId, employeeCode])\n  // The paginated GET /api/instructors route always orders by createdAt.\n  // (universityId, createdAt) replaces the bare (universityId) index below —\n  // universityId alone is a prefix of this composite, so the single-column\n  // index served no query the composite doesn't also serve, and dropping it\n  // avoids paying its write cost twice. (createdAt) is separate because it\n  // serves the ADMIN case with no universityId filter (a full-platform list);\n  // a composite index can't satisfy an ORDER BY on its second column without\n  // an equality condition on the first. Measured on a 20,514-row table:\n  // filtered case 6.6ms -> 0.07ms, unfiltered case 7.4ms -> 0.06ms (both via\n  // Sort-over-Seq-Scan -> Index Scan).\n  @@index([universityId, createdAt])\n  @@index([createdAt])\n  // Every manager-scoped report filters on this column.\n  @@index([managerId])\n}\n\n/// Activity taxonomy, held as DATA rather than a Prisma enum so a new type can\n/// be added by an admin without a migration or redeploy.\n///\n/// Business logic must branch on the BEHAVIOURAL FLAGS below, never on `code`.\n/// Keying off `code === \"DAILY_OPENING\"` would re-create the hard-coded enum\n/// this table exists to avoid, and a custom type added later would silently get\n/// none of the right treatment.\nmodel ActivityType {\n  id    String @id @default(cuid())\n  /// Stable machine identifier, e.g. DAILY_OPENING. Unique across the platform.\n  code  String @unique\n  label String\n\n  description String?\n  sortOrder   Int     @default(100)\n  isActive    Boolean @default(true)\n\n  /// Seeded types are structural; deleting one would break historical records.\n  isSystem Boolean @default(false)\n\n  // ---- Behavioural flags ----\n\n  /// At most one record per instructor per working day. True for DAILY_OPENING\n  /// and DAILY_CLOSING only. Phase 3 enforces this with a unique index on\n  /// (instructorId, workDate, activityTypeId) for types carrying this flag.\n  isOncePerDay Boolean @default(false)\n\n  /// Derived from the university's working-hours window rather than logged by\n  /// an instructor against a class. True for DAILY_OPENING / DAILY_CLOSING —\n  /// this is what stops them being generated per class.\n  isDerivedFromWorkingHours Boolean @default(false)\n\n  /// Counts toward productive/recognised time in the Phase 4 utilisation\n  /// numerator. False for UNUTILIZED.\n  countsAsProductive Boolean @default(true)\n\n  /// Represents known idle time. Distinct from MISSING_DATA, which is the\n  /// ABSENCE of any record and is therefore never a row in this table\n  /// (Phase 0 §3.5).\n  isUnutilized Boolean @default(false)\n\n  activityLogs ActivityLog[]\n\n  createdAt       DateTime         @default(now())\n  updatedAt       DateTime         @updatedAt\n  scheduleSlots   ScheduleSlot[]\n  workloadTargets WorkloadTarget[]\n\n  deliverableTypes DeliverableType[]\n\n  @@index([isActive, sortOrder])\n}\n\nenum LeaveStatus {\n  PENDING\n  APPROVED\n  REJECTED\n}\n\n/// Approved leave REMOVES a day from available capacity, so an instructor is\n/// never penalised in the utilisation percentage for a day they were not\n/// expected to work. This is distinct from ABSENCE (unapproved, capacity\n/// unchanged, a compliance signal) — see Phase 0 §3.6.\nmodel LeaveRequest {\n  id           String     @id @default(cuid())\n  instructorId String\n  instructor   Instructor @relation(fields: [instructorId], references: [id], onDelete: Cascade)\n\n  universityId String\n  university   University @relation(fields: [universityId], references: [id], onDelete: Restrict)\n\n  /// Inclusive calendar range in the university's own timezone.\n  startDate DateTime    @db.Date\n  endDate   DateTime    @db.Date\n  status    LeaveStatus @default(PENDING)\n  reason    String?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([instructorId, startDate, endDate])\n  @@index([universityId])\n  /// The analytics engine, exception detector, notification sweep and every\n  /// report run this exact predicate on every request:\n  ///   universityId = ? AND status = 'APPROVED' AND startDate <= ? AND endDate >= ?\n  /// `@@index([universityId])` alone leaves the status and period filters to a\n  /// row filter, which grows with a tenant's whole leave history.\n  @@index([universityId, status, startDate, endDate])\n}\n\n/// Server-side sessions (Phase 0 §2): revocable, and role/universityId are\n/// re-read from the User row on every request rather than trusted from a token.\n/// Only the SHA-256 of the token is stored, so a DB leak does not yield live\n/// session credentials.\nmodel Session {\n  id        String    @id @default(cuid())\n  tokenHash String    @unique\n  userId    String\n  user      User      @relation(fields: [userId], references: [id], onDelete: Cascade)\n  expiresAt DateTime\n  revokedAt DateTime?\n  userAgent String?\n  ipAddress String?\n  createdAt DateTime  @default(now())\n\n  @@index([userId])\n  @@index([expiresAt])\n}\n\nmodel ActivityLog {\n  id           String     @id @default(cuid())\n  instructorId String\n  instructor   Instructor @relation(fields: [instructorId], references: [id], onDelete: Cascade)\n\n  universityId String\n  university   University @relation(fields: [universityId], references: [id], onDelete: Restrict)\n\n  activityTypeId String\n  activityType   ActivityType @relation(fields: [activityTypeId], references: [id], onDelete: Restrict)\n\n  workDate  DateTime @db.Date\n  startTime DateTime\n  endTime   DateTime\n\n  /// Did the instructor actually GIVE this clock range, or did we place it?\n  ///\n  /// `startTime`/`endTime` are never null, because duration is derived from\n  /// them and every reader needs a range to derive it from. But a range is not\n  /// always something anybody said: the four-field form asks for hours and no\n  /// clock at all, and `placeOnDay` lays those end to end from the start of the\n  /// day. A narrative line can be either — \"9 to 11 took a lecture\" states one,\n  /// \"spent 2h on lab prep\" does not.\n  ///\n  /// Without this, a screen showing \"9 AM – 11 AM\" was presenting our\n  /// arithmetic as the instructor's testimony. Readers that have it show the\n  /// range when it was stated and the duration when it was not.\n  ///\n  /// Defaults FALSE: for a row written before this column existed we genuinely\n  /// do not know, and \"we placed it\" is the honest answer to that rather than a\n  /// claim nobody made. The migration backfills the narrative rows, which are\n  /// the ones most likely to have carried real times.\n  timesStated Boolean @default(false)\n\n  status  ActivityStatus @default(COMPLETED)\n  remarks String?\n\n  /// How the record came to exist (§15) — tells instructor-entered time apart\n  /// from schedule-derived or imported time when auditing.\n  source ActivitySource @default(INSTRUCTOR)\n\n  /// Optional links to the planned slot and the deliverable this work served.\n  scheduleSlot   ScheduleSlot? @relation(fields: [scheduleSlotId], references: [id], onDelete: SetNull)\n  scheduleSlotId String?\n  deliverable    Deliverable?  @relation(fields: [deliverableId], references: [id], onDelete: SetNull)\n  deliverableId  String?\n\n  /// Who wrote the record. Distinct from instructorId, which is its subject —\n  /// a manager may log on an instructor's behalf.\n  createdBy   User?   @relation(\"ActivityCreatedBy\", fields: [createdById], references: [id], onDelete: SetNull)\n  createdById String?\n\n  isOncePerDay Boolean @default(false)\n\n  /// The bullet this row was parsed from, exactly as the instructor typed it.\n  ///\n  /// Kept forever, and deliberately on the ROW rather than only on the\n  /// submission: somebody asking \"did the AI read this right?\" is looking at one\n  /// activity, and the answer has to sit beside it. Null for rows created by any\n  /// other path — a manager logging on somebody's behalf, or the importer.\n  rawText String?\n\n  /// The Deliverable Quantity box, exactly as typed — \"2\", \"2 classes\", \"?\".\n  ///\n  /// Beside `quantity`, not instead of it. `quantity` is the integer every\n  /// total is summed from; this is what the person actually wrote, and the\n  /// table prints it verbatim. They answer different questions: \"how many\"\n  /// against \"what did they say\".\n  ///\n  /// It exists because the two are not recoverable from each other. \"2\n  /// classes\" and \"2\" both parse to 2, and printing the parse back meant an\n  /// instructor could not find their own words on the screen — the same\n  /// failure `rawText` was added for.\n  ///\n  /// Null for rows created by any path that has no box: a manager logging on\n  /// somebody's behalf, the importer, the seed.\n  rawQuantity String?\n\n  /// The Working Hours box, exactly as typed — \"6h 00m\", \"6 hours 30 minutes\".\n  ///\n  /// Beside `startTime`/`endTime`, which remain the authority for every\n  /// computed duration. Same reasoning as `rawQuantity`: the clock positions\n  /// are what the arithmetic uses, and this is what was written.\n  rawWorkingHours String?\n\n  /// Which press of Submit produced this row. Null for non-worklog entries.\n  submissionId String?\n  submission   WorklogSubmission? @relation(fields: [submissionId], references: [id], onDelete: SetNull)\n\n  /// The specific deliverable the AI matched within the broad category, from the\n  /// fixed taxonomy. Null when nothing in the taxonomy fits, which is a real\n  /// answer rather than a failure.\n  /// Which subject this entry falls under — Technical, English, Aptitude,\n  /// Mathematics — as the reader judged it FROM THE SENTENCE.\n  ///\n  /// ── Why per entry, and not simply the instructor's own ────────────────\n  /// An instructor is filed under one stream, and that is what the client's\n  /// monthly sheet prints. But a day is not always one subject: the same\n  /// person can take a DSA class and then a communication session, and a\n  /// column that answered \"Technical\" for both would be describing the person\n  /// where the row is asking about the work.\n  ///\n  /// Nullable, and left null rather than guessed: a line like \"staff meeting\n  /// 2 to 3\" has no subject at all, and filling one in would be inventing the\n  /// most consequential column in the report.\n  broadCategoryId String?\n  broadCategory   InstructorCategory? @relation(fields: [broadCategoryId], references: [id], onDelete: Restrict)\n\n  deliverableTypeId String?\n  deliverableType   DeliverableType? @relation(fields: [deliverableTypeId], references: [id], onDelete: SetNull)\n\n  /// How many of that deliverable this row accounts for.\n  ///\n  /// ── NULL means the instructor never said ──────────────────────────────\n  /// Not missing data to be tidied away with a default — it is the client's\n  /// `?`. Their rule is explicit: \"graded some assignments\" with no number must\n  /// never become \"1 Assignment\", because the whole point of that column is how\n  /// many, and an invented one is indistinguishable from a real one once it is\n  /// in the sheet.\n  ///\n  /// It is deliberately not zero either. Zero is a count; \"none\" and \"unknown\"\n  /// are answers a manager acts on differently.\n  ///\n  /// A quantity of 1 is still written without anybody stating it, but only for\n  /// deliverables whose unit counts OCCURRENCES — a class, a meeting, a\n  /// workshop. There, the entry is one of them by definition. See `Counting` in\n  /// `@/domain/worklog-taxonomy`.\n  ///\n  /// The default stays 1 so every path that does not know about this — the\n  /// importer, a hand-written insert — keeps behaving as it did. Only the\n  /// parsers write null, and only where the client's rule says they must.\n  quantity Int? @default(1)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // Index set driven by the three measured dashboard queries (§33):\n  //   instructor dashboard -> (instructorId, workDate)\n  //   manager dashboard    -> (universityId, workDate)\n  //   manager drill-down   -> (universityId, instructorId, workDate)\n  // The bare (universityId) index is dropped: it is a prefix of the composite\n  // below, so it added write cost without serving any query.\n  //\n  // (instructorId, startTime) added for the paginated GET .../activities\n  // route: it filters by instructorId and orders by startTime, NOT workDate,\n  // so the index above left Postgres sorting every matching row before\n  // applying LIMIT. Measured on a 100k-row table, one instructor with 20k\n  // activities: 12.8ms (Sort over all 20k rows) -> 0.07ms (Index Scan\n  // stopping at LIMIT) for page one; page one is materially more common than\n  // deep pagination, so that is where this matters.\n  @@index([instructorId, startTime])\n  @@index([instructorId, workDate])\n  @@index([universityId, workDate])\n  @@index([universityId, instructorId, workDate])\n  @@index([scheduleSlotId])\n  @@index([deliverableId])\n  // The report groups by subject; without this that is a scan per week.\n  @@index([broadCategoryId])\n  // Superseding a day deletes by this. It had a foreign key and no index, so\n  // that delete was a sequential scan — 1,057 ms measured on 3.9M rows, on the\n  // path an instructor takes every time they correct their own day.\n  @@index([submissionId])\n}\n\nmodel Deliverable {\n  id           String     @id @default(cuid())\n  instructorId String\n  instructor   Instructor @relation(fields: [instructorId], references: [id], onDelete: Cascade)\n\n  universityId String\n  university   University @relation(fields: [universityId], references: [id], onDelete: Restrict)\n\n  title          String\n  description    String?\n  category       String?\n  targetQuantity Int\n  targetHours    Float\n  dueDate        DateTime @db.Date\n\n  status DeliverableStatus @default(NOT_STARTED)\n\n  createdBy   User?   @relation(\"DeliverableCreatedBy\", fields: [createdById], references: [id], onDelete: SetNull)\n  createdById String?\n\n  logs         DeliverableLog[]\n  activityLogs ActivityLog[]\n\n  deletedAt DateTime?\n  createdAt DateTime  @default(now())\n  updatedAt DateTime  @updatedAt\n\n  @@index([universityId, status])\n  @@index([instructorId, status])\n  @@index([universityId, dueDate])\n}\n\nmodel DeliverableLog {\n  id            String      @id @default(cuid())\n  deliverableId String\n  deliverable   Deliverable @relation(fields: [deliverableId], references: [id], onDelete: Cascade)\n\n  /// Carries its own tenant path rather than reaching it through Deliverable:\n  /// a tenant-scoped query must not require a join to be safe, and this is the\n  /// index the table is actually read by (§65).\n  universityId String\n  university   University @relation(fields: [universityId], references: [id], onDelete: Restrict)\n  instructorId String\n  instructor   Instructor @relation(fields: [instructorId], references: [id], onDelete: Cascade)\n\n  workDate          DateTime @db.Date\n  quantityCompleted Int\n  hoursSpent        Float\n  remarks           String?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([deliverableId, workDate])\n  @@index([universityId, instructorId, workDate])\n}\n\nenum InsightSeverity {\n  LOW\n  MEDIUM\n  HIGH\n  CRITICAL\n}\n\nenum InsightStatus {\n  NEW\n  READ\n  DISMISSED\n}\n\n/// Structured insight record (§27). Deliberately NOT free text: every insight\n/// carries the period it covers and the metric snapshot it was derived from, so\n/// the UI can show the supporting numbers behind any claim (§59).\nmodel AiInsight {\n  id String @id @default(cuid())\n\n  /// Scope determines which of the subject columns is populated. PLATFORM-scoped\n  /// insights have no university, which is why universityId is nullable.\n  scope        InsightScope @default(UNIVERSITY)\n  universityId String?\n  university   University?  @relation(fields: [universityId], references: [id], onDelete: Cascade)\n  instructorId String?\n  instructor   Instructor?  @relation(fields: [instructorId], references: [id], onDelete: Cascade)\n  managerId    String?\n  manager      Manager?     @relation(fields: [managerId], references: [id], onDelete: Cascade)\n\n  type           String\n  severity       InsightSeverity\n  title          String\n  summary        String\n  /// Retained for backwards compatibility with the existing rule set.\n  recommendation String\n\n  periodStart DateTime @db.Date\n  periodEnd   DateTime @db.Date\n  /// Human-readable period label, e.g. \"2026-09-07 to 2026-09-11\".\n  period      String\n\n  /// The exact metric snapshot the text was derived from.\n  sourceMetrics  Json\n  supportingData Json\n\n  status    InsightStatus @default(NEW)\n  expiresAt DateTime?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([universityId, createdAt])\n  @@index([instructorId, createdAt])\n  @@index([scope, status])\n}\n\nmodel AuditLog {\n  id String @id @default(cuid())\n\n  /// Nullable so a global ADMIN action is still recorded. Previously this was\n  /// required, so every admin action hit a `return` in the logger and was\n  /// silently dropped — the audit trail was blind to exactly the most\n  /// privileged actor.\n  universityId String?\n  university   University? @relation(fields: [universityId], references: [id], onDelete: Cascade)\n\n  userId String\n  user   User   @relation(fields: [userId], references: [id], onDelete: Restrict)\n\n  action     String\n  /// Entity type + id the action targeted, for drill-down from the log.\n  entityType String?\n  entityId   String?\n  metadata   Json?\n\n  createdAt DateTime @default(now())\n\n  @@index([universityId, createdAt])\n  @@index([userId, createdAt])\n  @@index([entityType, entityId])\n}\n\nmodel Notification {\n  id     String @id @default(cuid())\n  userId String\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  universityId String?\n  university   University? @relation(fields: [universityId], references: [id], onDelete: Cascade)\n\n  type    String    @default(\"GENERAL\")\n  title   String\n  message String\n  isRead  Boolean   @default(false)\n  /// Nullable timestamp rather than only a boolean, so \"when was this read\" is\n  /// answerable and the unread index stays selective.\n  readAt  DateTime?\n\n  /// Stable identity for a recurring condition, e.g. \"DELIVERABLE_DUE:<id>\".\n  /// The rollup runs hourly, so without this the same unresolved condition\n  /// would notify the same person every hour forever.\n  dedupeKey String?\n\n  createdAt DateTime @default(now())\n\n  /// One live notification per user per condition.\n  @@unique([userId, dedupeKey])\n  // §40: the unread-first query is (userId, readAt, createdAt).\n  @@index([userId, readAt, createdAt])\n}\n\n// ═══════════════════════════════════════════════════════════════════════════\n// ENUMS (added with the domain expansion)\n// ═══════════════════════════════════════════════════════════════════════════\n\nenum UniversityStatus {\n  ACTIVE\n  SUSPENDED\n  ARCHIVED\n}\n\n/// How an activity record came to exist (§15).\nenum ActivitySource {\n  SYSTEM\n  SCHEDULE\n  INSTRUCTOR\n  MANAGER\n  IMPORT\n  API\n}\n\nenum DeliverableStatus {\n  NOT_STARTED\n  IN_PROGRESS\n  COMPLETED\n  OVERDUE\n  CANCELLED\n}\n\nenum InsightScope {\n  PLATFORM\n  UNIVERSITY\n  MANAGER\n  INSTRUCTOR\n}\n\nenum LeaveType {\n  ANNUAL\n  SICK\n  UNPAID\n  BEREAVEMENT\n  OTHER\n}\n\nenum HolidayType {\n  PUBLIC\n  UNIVERSITY\n  OPTIONAL\n}\n\nenum TermStatus {\n  PLANNED\n  ACTIVE\n  COMPLETED\n  ARCHIVED\n}\n\nenum AssignmentStatus {\n  ACTIVE\n  COMPLETED\n  CANCELLED\n}\n\nenum ScheduleSlotStatus {\n  PLANNED\n  CONFIRMED\n  CANCELLED\n}\n\nenum ReportingPeriodType {\n  DAILY\n  WEEKLY\n  MONTHLY\n  CUSTOM\n}\n\nenum ReportJobStatus {\n  QUEUED\n  RUNNING\n  COMPLETED\n  FAILED\n}\n\n// ═══════════════════════════════════════════════════════════════════════════\n// TENANCY — configuration split out of the University row (§9)\n// ═══════════════════════════════════════════════════════════════════════════\n\n/// One row per university. Kept separate from `University` so operational\n/// configuration can grow without widening the tenant identity row that is\n/// read on nearly every request.\nmodel UniversitySettings {\n  id           String     @id @default(cuid())\n  universityId String     @unique\n  university   University @relation(fields: [universityId], references: [id], onDelete: Cascade)\n\n  /// Free-form policy blobs. Deliberately Json: these are read whole by the\n  /// calculation service and never filtered on, so columns would add migration\n  /// churn for no query benefit.\n  utilizationConfig     Json?\n  activityLoggingPolicy Json?\n  defaultBreakPolicy    Json?\n\n  /// Retention window for raw activity records, in days. Null = keep forever.\n  activityRetentionDays Int?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\n// ═══════════════════════════════════════════════════════════════════════════\n// ACADEMIC STRUCTURE (§18, §19)\n// ═══════════════════════════════════════════════════════════════════════════\n\nmodel Department {\n  id           String     @id @default(cuid())\n  universityId String\n  university   University @relation(fields: [universityId], references: [id], onDelete: Cascade)\n\n  name String\n  code String\n\n  programs  Program[]\n  courses   Course[]\n  deletedAt DateTime?\n  createdAt DateTime  @default(now())\n  updatedAt DateTime  @updatedAt\n\n  /// Tenant-scoped uniqueness (§34): two universities may both have \"CS\".\n  @@unique([universityId, code])\n  @@index([universityId])\n}\n\nmodel Program {\n  id           String      @id @default(cuid())\n  universityId String\n  university   University  @relation(fields: [universityId], references: [id], onDelete: Cascade)\n  departmentId String?\n  department   Department? @relation(fields: [departmentId], references: [id], onDelete: SetNull)\n\n  name String\n  code String\n\n  courses   Course[]\n  deletedAt DateTime?\n  createdAt DateTime  @default(now())\n  updatedAt DateTime  @updatedAt\n\n  @@unique([universityId, code])\n  @@index([universityId])\n}\n\nmodel AcademicTerm {\n  id           String     @id @default(cuid())\n  universityId String\n  university   University @relation(fields: [universityId], references: [id], onDelete: Cascade)\n\n  name      String\n  startDate DateTime   @db.Date\n  endDate   DateTime   @db.Date\n  status    TermStatus @default(PLANNED)\n\n  assignments CourseAssignment[]\n  schedules   Schedule[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@unique([universityId, name])\n  @@index([universityId, startDate, endDate])\n}\n\nmodel Course {\n  id           String      @id @default(cuid())\n  universityId String\n  university   University  @relation(fields: [universityId], references: [id], onDelete: Cascade)\n  departmentId String?\n  department   Department? @relation(fields: [departmentId], references: [id], onDelete: SetNull)\n  programId    String?\n  program      Program?    @relation(fields: [programId], references: [id], onDelete: SetNull)\n\n  code    String\n  title   String\n  credits Int?\n\n  assignments   CourseAssignment[]\n  scheduleSlots ScheduleSlot[]\n\n  deletedAt DateTime?\n  createdAt DateTime  @default(now())\n  updatedAt DateTime  @updatedAt\n\n  @@unique([universityId, code])\n  @@index([universityId])\n}\n\n/// An instructor teaches a course for a term. Modelled as its own table rather\n/// than a column on the instructor so teaching history is preserved when\n/// assignments change (§19).\nmodel CourseAssignment {\n  id             String        @id @default(cuid())\n  universityId   String\n  university     University    @relation(fields: [universityId], references: [id], onDelete: Cascade)\n  courseId       String\n  course         Course        @relation(fields: [courseId], references: [id], onDelete: Cascade)\n  instructorId   String\n  instructor     Instructor    @relation(fields: [instructorId], references: [id], onDelete: Cascade)\n  academicTermId String?\n  academicTerm   AcademicTerm? @relation(fields: [academicTermId], references: [id], onDelete: SetNull)\n\n  role      String?\n  startDate DateTime?        @db.Date\n  endDate   DateTime?        @db.Date\n  status    AssignmentStatus @default(ACTIVE)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@unique([courseId, instructorId, academicTermId])\n  @@index([universityId, instructorId])\n  @@index([universityId, courseId])\n}\n\n// ═══════════════════════════════════════════════════════════════════════════\n// SCHEDULING (§17, §24)\n// ═══════════════════════════════════════════════════════════════════════════\n\nmodel Schedule {\n  id             String        @id @default(cuid())\n  universityId   String\n  university     University    @relation(fields: [universityId], references: [id], onDelete: Cascade)\n  instructorId   String\n  instructor     Instructor    @relation(fields: [instructorId], references: [id], onDelete: Cascade)\n  academicTermId String?\n  academicTerm   AcademicTerm? @relation(fields: [academicTermId], references: [id], onDelete: SetNull)\n\n  name      String?\n  startDate DateTime @db.Date\n  endDate   DateTime @db.Date\n\n  slots     ScheduleSlot[]\n  createdAt DateTime       @default(now())\n  updatedAt DateTime       @updatedAt\n\n  @@index([universityId, instructorId])\n}\n\n/// One planned block of an instructor's day. Relational rather than a JSON\n/// document so slots can be indexed, validated, and compared against what was\n/// actually logged (§17).\nmodel ScheduleSlot {\n  id           String     @id @default(cuid())\n  universityId String\n  university   University @relation(fields: [universityId], references: [id], onDelete: Cascade)\n  scheduleId   String?\n  schedule     Schedule?  @relation(fields: [scheduleId], references: [id], onDelete: Cascade)\n  instructorId String\n  instructor   Instructor @relation(fields: [instructorId], references: [id], onDelete: Cascade)\n  courseId     String?\n  course       Course?    @relation(fields: [courseId], references: [id], onDelete: SetNull)\n\n  activityTypeId String\n  activityType   ActivityType @relation(fields: [activityTypeId], references: [id], onDelete: Restrict)\n\n  /// Local calendar date in the university's timezone, matching ActivityLog.\n  workDate  DateTime           @db.Date\n  startTime DateTime\n  endTime   DateTime\n  location  String?\n  status    ScheduleSlotStatus @default(PLANNED)\n\n  activityLogs ActivityLog[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([universityId, workDate])\n  @@index([instructorId, workDate])\n  @@index([universityId, instructorId, workDate])\n}\n\n/// Recurring non-working break inside the working day. Per-university and\n/// per-weekday, because break schedules are not uniform across tenants (§24).\nmodel BreakPolicy {\n  id           String     @id @default(cuid())\n  universityId String\n  university   University @relation(fields: [universityId], references: [id], onDelete: Cascade)\n\n  name        String\n  /// Null = applies to every working day.\n  dayOfWeek   Int?\n  startMinute Int\n  endMinute   Int\n  isActive    Boolean @default(true)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([universityId, isActive])\n}\n\n// ═══════════════════════════════════════════════════════════════════════════\n// WORKLOAD TARGETS & REPORTING PERIODS (§21, §22)\n// ═══════════════════════════════════════════════════════════════════════════\n\n/// Per-university expectation for how much time an activity type should take.\n/// Effective-dated so changing a target does not rewrite history.\nmodel WorkloadTarget {\n  id           String     @id @default(cuid())\n  universityId String\n  university   University @relation(fields: [universityId], references: [id], onDelete: Cascade)\n\n  /// Null instructorId = the university-wide default for this activity type.\n  instructorId String?\n  instructor   Instructor? @relation(fields: [instructorId], references: [id], onDelete: Cascade)\n\n  activityTypeId String?\n  activityType   ActivityType? @relation(fields: [activityTypeId], references: [id], onDelete: Cascade)\n\n  targetMinutes Int\n  periodType    ReportingPeriodType @default(WEEKLY)\n  effectiveFrom DateTime            @db.Date\n  effectiveTo   DateTime?           @db.Date\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([universityId, activityTypeId, effectiveFrom])\n  @@index([instructorId, effectiveFrom])\n}\n\nmodel ReportingPeriod {\n  id           String      @id @default(cuid())\n  universityId String?\n  university   University? @relation(fields: [universityId], references: [id], onDelete: Cascade)\n\n  type      ReportingPeriodType\n  name      String\n  startDate DateTime            @db.Date\n  endDate   DateTime            @db.Date\n\n  createdAt DateTime @default(now())\n\n  @@unique([universityId, type, startDate, endDate])\n  @@index([universityId, startDate])\n}\n\n// ═══════════════════════════════════════════════════════════════════════════\n// ANALYTICS SUMMARY TABLES (§29, §30)\n// ═══════════════════════════════════════════════════════════════════════════\n//\n// These exist because the admin dashboard query measured as a Parallel Seq Scan\n// over ActivityLog (399 ms at 100 universities / 3.9M rows). No index fixes a\n// full-platform aggregate — the fix is to aggregate once per day in a job and\n// have dashboards read the rollup. Raw ActivityLog remains the source of truth\n// and is used for drill-down (§60).\n//\n// Minutes, not hours: integers avoid float drift when summing millions of rows.\n\nmodel InstructorDailyMetric {\n  id           String     @id @default(cuid())\n  universityId String\n  university   University @relation(fields: [universityId], references: [id], onDelete: Cascade)\n  instructorId String\n  instructor   Instructor @relation(fields: [instructorId], references: [id], onDelete: Cascade)\n\n  metricDate DateTime @db.Date\n\n  capacityMinutes    Int @default(0)\n  productiveMinutes  Int @default(0)\n  unutilizedMinutes  Int @default(0)\n  /// Capacity on an expected working day with no records at all. Never folded\n  /// into unutilized — \"we don't know\" is not \"they did nothing\" (§23).\n  missingDataMinutes Int @default(0)\n  overlapMinutes     Int @default(0)\n\n  /// Per-activity-type breakdown, keyed by activity type code.\n  minutesByActivityType Json @default(\"{}\")\n\n  isWorkingDay     Boolean @default(true)\n  nonWorkingReason String?\n  openingLogged    Boolean @default(false)\n  closingLogged    Boolean @default(false)\n\n  utilizationPercent Float?\n\n  computedAt DateTime @default(now())\n  updatedAt  DateTime @updatedAt\n\n  /// One row per instructor per day; the job upserts on this key.\n  @@unique([instructorId, metricDate])\n  @@index([universityId, metricDate])\n  @@index([universityId, instructorId, metricDate])\n}\n\nmodel InstructorWeeklyMetric {\n  id           String     @id @default(cuid())\n  universityId String\n  university   University @relation(fields: [universityId], references: [id], onDelete: Cascade)\n  instructorId String\n  instructor   Instructor @relation(fields: [instructorId], references: [id], onDelete: Cascade)\n\n  periodStart DateTime @db.Date\n  periodEnd   DateTime @db.Date\n\n  capacityMinutes    Int @default(0)\n  productiveMinutes  Int @default(0)\n  unutilizedMinutes  Int @default(0)\n  missingDataMinutes Int @default(0)\n\n  minutesByActivityType Json   @default(\"{}\")\n  utilizationPercent    Float?\n  openingCompliancePct  Float?\n  closingCompliancePct  Float?\n  expectedWorkingDays   Int    @default(0)\n\n  computedAt DateTime @default(now())\n  updatedAt  DateTime @updatedAt\n\n  @@unique([instructorId, periodStart])\n  @@index([universityId, periodStart])\n}\n\n/// What the admin dashboard reads instead of scanning ActivityLog.\nmodel UniversityDailyMetric {\n  id           String     @id @default(cuid())\n  universityId String\n  university   University @relation(fields: [universityId], references: [id], onDelete: Cascade)\n\n  metricDate DateTime @db.Date\n\n  activeInstructors  Int @default(0)\n  capacityMinutes    Int @default(0)\n  productiveMinutes  Int @default(0)\n  unutilizedMinutes  Int @default(0)\n  missingDataMinutes Int @default(0)\n\n  minutesByActivityType Json   @default(\"{}\")\n  utilizationPercent    Float?\n  openingCompliancePct  Float?\n  closingCompliancePct  Float?\n\n  /// The counts those percentages are made of.\n  ///\n  /// Stored because a period's compliance is not the average of its days'\n  /// compliance. The live engine computes openings over expected instructor-\n  /// days — a ratio of sums — while the dashboard averaged the stored daily\n  /// percentages, and an unweighted mean of ratios disagrees with a ratio of\n  /// sums the moment the denominators differ. Approved leave and part-week\n  /// holidays make them differ constantly.\n  ///\n  /// The rollup already had these in hand and threw them away.\n  openingsLogged         Int @default(0)\n  closingsLogged         Int @default(0)\n  /// Instructor-days expected on this date: the denominator of both figures.\n  expectedInstructorDays Int @default(0)\n\n  /// The two numbers the Active-Instructor Average Hours feature divides.\n  ///\n  /// \"Active\" = this instructor's `productiveMinutes` that day was > 0. An\n  /// instructor with no submission and one whose entries summed to exactly\n  /// 0m are the same case here — both are absent from both fields below,\n  /// never present as a zero. See `src/domain/average-hours.ts` for the\n  /// confirmed formula these feed: sum every day's minutes, sum every day's\n  /// count, divide once — never an average of daily averages.\n  activeInstructorMinutes Int @default(0)\n  activeInstructorCount   Int @default(0)\n\n  computedAt DateTime @default(now())\n  updatedAt  DateTime @updatedAt\n\n  @@unique([universityId, metricDate])\n  @@index([metricDate])\n}\n\n// ═══════════════════════════════════════════════════════════════════════════\n// REPORTING JOBS (§41)\n// ═══════════════════════════════════════════════════════════════════════════\n\n/// Large exports are queued, not generated inside the request. The row is the\n/// handover point between the API and a background worker.\nmodel ReportJob {\n  id           String      @id @default(cuid())\n  universityId String?\n  university   University? @relation(fields: [universityId], references: [id], onDelete: Cascade)\n\n  requestedById String\n  requestedBy   User   @relation(fields: [requestedById], references: [id], onDelete: Cascade)\n\n  reportType String\n  format     String          @default(\"CSV\")\n  parameters Json            @default(\"{}\")\n  status     ReportJobStatus @default(QUEUED)\n\n  /// Object-storage key once generated; never the file contents.\n  resultUrl    String?\n  errorMessage String?\n  rowCount     Int?\n\n  startedAt   DateTime?\n  completedAt DateTime?\n  createdAt   DateTime  @default(now())\n  updatedAt   DateTime  @updatedAt\n\n  @@index([universityId, createdAt])\n  @@index([status, createdAt])\n}\n\nenum MetricsJobTrigger {\n  SCHEDULED\n  MANUAL\n  SEED\n}\n\nenum MetricsJobStatus {\n  RUNNING\n  COMPLETED\n  FAILED\n}\n\n/// Execution record for the metric rollup.\n///\n/// Exists so \"are the dashboards current?\" is answerable without guessing. It\n/// deliberately is NOT an AuditLog row: AuditLog.userId is non-null because\n/// every entry there is an act by a person, and a scheduled job has no actor.\nmodel MetricsJobRun {\n  id      String            @id @default(cuid())\n  trigger MetricsJobTrigger\n  status  MetricsJobStatus  @default(RUNNING)\n\n  /// Window recomputed, as YYYY-MM-DD.\n  fromDate String\n  toDate   String\n\n  universitiesProcessed  Int @default(0)\n  instructorDaysWritten  Int @default(0)\n  instructorWeeksWritten Int @default(0)\n\n  errorMessage String?\n  startedAt    DateTime  @default(now())\n  completedAt  DateTime?\n  durationMs   Int?\n\n  @@index([status, startedAt])\n  @@index([startedAt])\n}\n\n// ═══════════════════════════════════════════════════════════════════════════\n// BULK IMPORT — onboarding an existing organisation from a file\n// ═══════════════════════════════════════════════════════════════════════════\n\nenum ImportSourceType {\n  CSV\n  PDF\n}\n\nenum ImportStatus {\n  /// Parsed, awaiting column mapping.\n  UPLOADED\n  /// Mapping decided, awaiting validation.\n  MAPPED\n  /// Validated; the preview is ready and the admin has not confirmed yet.\n  VALIDATED\n  /// Confirmed and being written, in batches.\n  PROCESSING\n  COMPLETED\n  COMPLETED_WITH_WARNINGS\n  FAILED\n}\n\n/// One bulk import, from upload to written rows.\n///\n/// ── Why this table exists at all ───────────────────────────────────────────\n/// A row here is not architecture for its own sake; four requirements make it\n/// unavoidable, and each one is a requirement the feature cannot drop:\n///\n///   1. The workflow is four steps (upload -> map -> validate -> confirm) and\n///      the dataset has to survive between them. The alternative is making the\n///      browser re-upload a 10,000-row file at every step.\n///   2. Writing 10,000 rows cannot finish inside one HTTP request, so the\n///      request must hand off and the client must be able to ask \"how far\".\n///   3. \"Who imported what, and what did it do\" has to be answerable later.\n///   4. Re-running an interrupted import must not duplicate anything, which\n///      needs the parsed rows and the progress counter to be durable.\n///\n/// ── Why not an AuditLog row ────────────────────────────────────────────────\n/// The same reason `MetricsJobRun` is not one: `AuditLog.userId` is NOT NULL,\n/// and progress is written repeatedly by background work with no actor at the\n/// keyboard. The audit trail still records the import as an event — this table\n/// records its execution. Neither replaces the other.\n///\n/// ── What is deliberately NOT stored ────────────────────────────────────────\n/// Not the uploaded file, and no credential. `rows` holds the PARSED,\n/// structurally-typed records only, which is what steps 2-4 operate on; the\n/// original bytes are dropped once parsed. The batch password supplied at\n/// confirmation is hashed and used, never written here.\nmodel ImportJob {\n  id String @id @default(cuid())\n\n  /// Restrict, not Cascade: import history outlives the admin who ran it.\n  /// (`ReportJob` uses Cascade and loses its history with the user; that is the\n  /// wrong trade for a record of what entered the database.)\n  createdById String\n  createdBy   User   @relation(\"ImportJobCreatedBy\", fields: [createdById], references: [id], onDelete: Restrict)\n\n  sourceType ImportSourceType\n  fileName   String\n  fileSize   Int\n  /// SHA-256 of the uploaded bytes. Not a uniqueness constraint: re-importing a\n  /// corrected file is legitimate, and the upsert is idempotent regardless. It\n  /// is here so the UI can warn \"this exact file was already imported\".\n  checksum   String\n\n  status ImportStatus @default(UPLOADED)\n\n  /// Source column header -> canonical field name, as confirmed by the admin.\n  mapping Json @default(\"{}\")\n  /// The parsed records. Structurally typed, never the raw file.\n  rows    Json @default(\"[]\")\n\n  rowCount      Int @default(0)\n  processedRows Int @default(0)\n\n  /// Bounded diagnostics — the first N of each, never the whole dataset.\n  errors   Json @default(\"[]\")\n  warnings Json @default(\"[]\")\n  /// Preview counts before confirmation, outcome counts after.\n  summary  Json @default(\"{}\")\n\n  /// Populated only for PDF, where extraction is interpretive.\n  extractionConfidence String?\n  errorMessage         String?\n\n  startedAt   DateTime?\n  completedAt DateTime?\n  createdAt   DateTime  @default(now())\n  updatedAt   DateTime  @updatedAt\n\n  @@index([status, createdAt])\n  @@index([createdById, createdAt])\n  @@index([checksum])\n}\n\n// ═══════════════════════════════════════════════════════════════════════════\n// FREE-TEXT WORKLOG — what the instructor wrote, and what was parsed from it\n// ═══════════════════════════════════════════════════════════════════════════\n\n/// One deliverable within a broad category — \"Lecture\" inside Teaching.\n///\n/// ── Why this is a table and not a string on ActivityLog ────────────────────\n/// It is a CLOSED vocabulary the client supplied, and closed vocabularies stop\n/// being closed the moment they are free text: \"Lecture\", \"lecture\" and \"Lec\"\n/// become three deliverables and the sheet's quantity column stops adding up.\n/// A foreign key makes the AI's output checkable — a deliverable that is not in\n/// this table simply cannot be written.\n///\n/// ── Not the same thing as `Deliverable` ────────────────────────────────────\n/// `Deliverable` is a piece of work ASSIGNED to one instructor, with a target\n/// and a due date. This is the taxonomy those pieces of work are classified by.\n/// They are different nouns that unfortunately share a word.\nmodel DeliverableType {\n  id    String @id @default(cuid())\n  /// Stable machine name, e.g. `LECTURE`. What the parser is allowed to emit.\n  code  String @unique\n  label String\n\n  /// The broad category this belongs under.\n  activityTypeId String\n  activityType   ActivityType @relation(fields: [activityTypeId], references: [id], onDelete: Restrict)\n\n  sortOrder Int     @default(100)\n  isActive  Boolean @default(true)\n\n  /// Whether a COUNT of this means anything.\n  ///\n  /// The client's monthly sheet lists every kind of work with its hours, but\n  /// counts only some of them: \"12 Classes, 6 Assignments, 3 Doubt Sessions\"\n  /// beside a deliverable list that also held Lesson Prep and Meetings/Reports.\n  /// That is not an omission — \"6 lesson preps\" is not a sentence anybody says.\n  /// Preparation, meetings, reporting and admin are EFFORT: their hours are\n  /// real and are reported, but they have no unit to be counted in.\n  ///\n  /// Defaulted true because most are countable, and because a wrong default\n  /// that shows a number is easier to notice than one that hides it.\n  isCountable Boolean @default(true)\n\n  activityLogs ActivityLog[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([activityTypeId, sortOrder])\n}\n\n/// Whether a submission may be recorded, or needs a manager's agreement first.\nenum WorklogApproval {\n  /// Written on the day, inside the university's hours, describing work inside\n  /// them. The ordinary case, and it needs nobody's permission.\n  NOT_REQUIRED\n  PENDING\n  APPROVED\n  REJECTED\n}\n\n/// Why a submission needed asking about. Both can apply at once.\nenum WorklogExceptionReason {\n  /// Submitted outside the university's working hours.\n  SUBMITTED_OFF_HOURS\n  /// One or more activities fall outside the working-hours window.\n  ACTIVITY_OFF_HOURS\n  /// Both of the above.\n  BOTH\n}\n\nenum WorklogParseStatus {\n  /// Saved, not yet parsed. The instructor's text is already safe at this point.\n  PENDING\n  /// A read is running right now.\n  ///\n  /// Distinct from PENDING because they answer different questions and the\n  /// screen says different things: PENDING is \"queued\", PROCESSING is\n  /// \"analysing your worklog\". It also survives a restart, which the in-process\n  /// in-flight set cannot — a submission left PROCESSING by a killed process is\n  /// visibly stuck rather than invisibly abandoned.\n  PROCESSING\n  /// Read, and the activities written. The completed state.\n  PARSED\n  /// The provider could not be reached, or returned nothing usable. The raw text\n  /// is intact and the submission can be parsed again.\n  FAILED\n}\n\n/// How the instructor typed the day, which decides how it is read.\nenum WorklogInputMode {\n  /// One line per activity, already separated by the person who wrote it.\n  BULLETS\n  /// A paragraph in their own words, from which the activities are found.\n  NARRATIVE\n}\n\n/// One press of Submit: the bullets exactly as typed, and the clock they start.\n///\n/// ── Why this exists rather than living on ActivityLog ──────────────────────\n/// Three requirements need a row that is neither an activity nor an instructor:\n///\n///   1. The text must survive a parsing failure. Saving the submission FIRST and\n///      parsing afterwards is what makes \"the instructor's data is never lost\"\n///      true rather than aspirational.\n///   2. The review clock is PER SUBMISSION — two submissions on two days each\n///      run their own — so it needs somewhere to live that is not the instructor\n///      and not any one activity.\n///   3. A bullet can fail to parse while its siblings succeed. This row holds\n///      every bullet; `ActivityLog` holds only the ones that became work.\nmodel WorklogSubmission {\n  id String @id @default(cuid())\n\n  instructorId String\n  instructor   Instructor @relation(fields: [instructorId], references: [id], onDelete: Cascade)\n  universityId String\n  university   University @relation(fields: [universityId], references: [id], onDelete: Restrict)\n\n  /// The day being logged, in the university's zone.\n  workDate DateTime @db.Date\n\n  /// The bullets, in order, exactly as typed. Never rewritten by parsing.\n  rawBullets Json\n\n  /// Which reader this submission needs. Persisted rather than inferred: the\n  /// read happens in the background, after the request that knew is gone, and a\n  /// paragraph read as bullets is one activity instead of five.\n  inputMode WorklogInputMode @default(BULLETS)\n\n  status     WorklogParseStatus @default(PENDING)\n  /// Why parsing failed, in words an instructor can act on. Never a stack trace.\n  parseError String?\n\n  /// The bullets that produced no activity, each with the reason, in bullet\n  /// order: `[{ index, rawText, reason }]`.\n  ///\n  /// Without this the review view can only tell an instructor that a line is\n  /// missing, which is the least useful half of the answer — \"no time could be\n  /// read from this line\" and \"this overlaps 14:00–15:00\" ask for completely\n  /// different corrections. The reason is produced while writing and is not\n  /// recoverable afterwards, so it is kept rather than recomputed.\n  ///\n  /// Rewritten in full on every parse, so a re-parse that succeeds clears what\n  /// the failed one recorded.\n  rejections Json?\n\n  /// t0. The review clock runs from here and from nothing else — how fast\n  /// parsing happened must not move anybody's deadline.\n  submittedAt DateTime  @default(now())\n  parsedAt    DateTime?\n\n  /// Replaced by a later submission for the same day.\n  ///\n  /// ── Why the old one is kept at all ────────────────────────────────────\n  /// Editing a day means \"this is what happened, not what I said before\", so\n  /// the ACTIVITIES from the earlier text are removed — they no longer describe\n  /// anything. The submission itself stays, marked here, because it is the\n  /// record of what the instructor actually wrote at the time, and deleting\n  /// somebody's own words to make a screen tidier is not a trade this product\n  /// makes. Reads filter it out; the audit trail can still find it.\n  supersededAt DateTime?\n\n  /// When the instructor first corrected a parsed entry from this submission.\n  /// Its presence at the three-hour mark is the whole escalation decision.\n  reviewedAt DateTime?\n\n  /// When the manager was told. Set once and never cleared: a later correction\n  /// adds `reviewedAt` beside it rather than erasing the fact that it was\n  /// escalated, because \"flagged and then fixed\" and \"never flagged\" are\n  /// different histories and a manager is entitled to tell them apart.\n  escalatedAt DateTime?\n\n  /// The read succeeded, but something about it wants the instructor's eye.\n  ///\n  /// Distinct from `rejections`, which says a line produced nothing at all, and\n  /// from `parseError`, which says the read failed. This is the middle state the\n  /// client asked for: the day was organised, and an activity has no times, or\n  /// two of them overlap, or the paragraph mentions a clock time that did not\n  /// end up against anything. Nothing is wrong with the record — it is complete\n  /// and correct as far as it goes — and a person is the only one who can say\n  /// whether it goes far enough.\n  needsReview Boolean @default(false)\n\n  /// Why, in words the instructor can act on: `[{ kind, message }]`. Rewritten\n  /// in full on every parse, so a re-read that comes back clean clears them.\n  reviewNotes Json?\n\n  /**\n   * ── Approval ─────────────────────────────────────────────────────────────\n   * An instructor records their OWN day, inside their university's hours, and\n   * that needs no permission — the overwhelming case is `NOT_REQUIRED` and it\n   * costs a manager nothing.\n   * What is asked about is work that falls outside those hours, or a day\n   * written up after them. Both are legitimate — people stay late — but both\n   * are also how a timesheet quietly stops reflecting the working day it is\n   * measured against, so a person rather than a rule decides.\n   * The submission itself carries this rather than a separate request table:\n   * what a manager needs in order to decide IS the submission — the sentences,\n   * the times, and what they were read as. A request row pointing at it would\n   * be the same thing with an extra join.\n   */\n  approval        WorklogApproval         @default(NOT_REQUIRED)\n  exceptionReason WorklogExceptionReason?\n  decidedById     String?\n  decidedBy       User?                   @relation(\"WorklogDecidedBy\", fields: [decidedById], references: [id], onDelete: SetNull)\n  decidedAt       DateTime?\n  /// The manager's own words, shown to the instructor. Never a code.\n  decisionNote    String?\n\n  activities ActivityLog[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // The escalation sweep reads exactly this shape: not yet escalated, not yet\n  // reviewed, old enough to be due.\n  @@index([escalatedAt, reviewedAt, submittedAt])\n  // The manager's queue: everything waiting on them, oldest first.\n  @@index([approval, universityId, submittedAt])\n  @@index([instructorId, workDate])\n  // Reads want the day's LIVE submissions, never the replaced ones.\n  @@index([instructorId, workDate, supersededAt])\n  @@index([status, submittedAt])\n}\n\n/// One day's worklog, normalised for reading.\n///\n/// ── Why this is a cache and never a source ────────────────────────────────\n/// The instructor's own words stay in `ActivityLog.rawText`, untouched. This\n/// holds what a model made of them: better names for the activities, a label\n/// for what each one is counted in, and tidied remarks.\n///\n/// It holds NO numbers taken from the model. `groups` records which source rows\n/// each named group covers, and every duration and quantity on screen is summed\n/// from those rows at read time. A model that miscounts therefore cannot put a\n/// wrong figure in front of anybody — it has no figures to give.\n///\n/// `sourceFingerprint` is taken over the activities it was built from. Correct\n/// one of them and the fingerprint stops matching, so the row is stale and is\n/// rebuilt rather than shown against data it no longer describes.\nmodel WorklogDaySummary {\n  id String @id @default(cuid())\n\n  instructorId String\n  instructor   Instructor @relation(fields: [instructorId], references: [id], onDelete: Cascade)\n  universityId String\n  university   University @relation(fields: [universityId], references: [id], onDelete: Cascade)\n\n  /// The day, in the university's zone.\n  workDate DateTime @db.Date\n\n  /// Over the source activities. A mismatch means rebuild.\n  sourceFingerprint String\n\n  /// `[{ name, quantityLabel, sourceIds }]`. Names and labels only — no figures.\n  groups Json\n\n  /// Normalised remarks, as a list of strings.\n  remarks Json\n\n  /// The deterministic total at the time it was written, for a cheap check.\n  totalMinutes Int\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@unique([instructorId, workDate])\n  @@index([universityId, workDate])\n}\n\n/// One cached AI insight per (instructor, scope, period).\n///\n/// The insight is generated at most once per distinct state of the underlying\n/// work logs. `contextHash` is what decides that: it is SHA-256 over the\n/// canonical context, the prompt version and the model id, so a data edit, a\n/// prompt edit and a model switch all invalidate by the same comparison.\n///\n/// Invalidation is content-based ONLY. There is no TTL and no scheduled\n/// regeneration — an insight that still matches its data is still correct\n/// however old it is, and one that does not is wrong however fresh.\n///\n/// Nothing cascades. Changing a day changes the DAY hash, and also the WEEK and\n/// MONTH hashes, because those contexts contain that day's rows. That falls out\n/// of hashing and needs no code.\nmodel AiInsightCache {\n  id String @id @default(cuid())\n\n  instructorId String\n  instructor   Instructor @relation(fields: [instructorId], references: [id], onDelete: Cascade)\n\n  scopeType   InsightScopeType\n  periodStart DateTime         @db.Date\n  periodEnd   DateTime         @db.Date\n\n  /// SHA-256 hex of canonical JSON + prompt version + model id.\n  contextHash String @db.Char(64)\n\n  /// The frozen combined context of every day in the period.\n  ///\n  /// Looks redundant against `WorklogEntry` and is not. That table is LIVE — the\n  /// instructor can edit any day at any moment. This is what the insight was\n  /// actually built from, frozen at generation.\n  ///\n  /// Comparing the two is how staleness is detected, and it is the only way to\n  /// answer \"what was this insight based on?\" — the question asked the first\n  /// time an insight looks wrong in front of a client. Never write it without\n  /// writing `insightPayload`, `contextHash` and `generatedAt` in the same\n  /// transaction: the four are one fact and disagree only if something is broken.\n  rawContext Json\n\n  /// The model's reply, stored as returned.\n  insightPayload Json\n\n  promptVersion String\n  modelId       String\n\n  status InsightCacheStatus @default(READY)\n\n  generatedAt  DateTime  @default(now())\n  lastServedAt DateTime?\n  /// Incremented on every cache hit. This is how the saving is measured.\n  serveCount   Int       @default(0)\n\n  /// CONSECUTIVE failures; reset to zero by any success. At three the view\n  /// stops trying on its own and offers a manual retry instead, so a broken\n  /// provider cannot be re-billed once per page load.\n  failureCount Int     @default(0)\n  lastError    String?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  /// One row per scope: the cache is keyed by what it describes, not by when it\n  /// was written, so a regeneration replaces rather than accumulates.\n  @@unique([instructorId, scopeType, periodStart, periodEnd])\n  @@index([contextHash])\n}\n\nenum InsightScopeType {\n  DAY\n  WEEK\n  MONTH\n}\n\nenum InsightCacheStatus {\n  READY\n  GENERATING\n  FAILED\n}\n\n/// One row per instructor per day. The only source of truth.\n///\n/// ── The shape is the form ─────────────────────────────────────────────────\n/// Four fields, and they are exactly the four boxes an instructor fills in: what\n/// they did, how much of it, how long the day was, and a note. Nothing here is\n/// derived and nothing is parsed on the way in.\n///\n/// An earlier shape held a JSON array of activities, parsed out of the text at\n/// write time. That put a parser between somebody and their own words, and made\n/// the stored row a claim about what they meant rather than a record of what\n/// they wrote. The structure is now derived AFTER the fact, into\n/// `DayExtraction`, where it can be wrong without damaging the record.\nmodel WorklogEntry {\n  id String @id @default(cuid())\n\n  instructorId String\n  instructor   Instructor @relation(fields: [instructorId], references: [id], onDelete: Cascade)\n\n  /// Carried on the row rather than reached through the instructor: every read\n  /// is tenant-scoped, and a join for the boundary check is a join that can be\n  /// forgotten.\n  universityId String\n  university   University @relation(fields: [universityId], references: [id], onDelete: Restrict)\n\n  /// The day the work was done, in the university's zone.\n  logDate DateTime @db.Date\n\n  /// What they did, in their own words. Typically names how many and how long.\n  deliverable String\n\n  /// A corroborating note — \"5 class\", \"2 batches\", \"half day\", or nothing.\n  /// Free text, stored and shown verbatim, never coerced to a number.\n  deliverableQuantity String?\n\n  /// The day's total, entered SEPARATELY by the instructor.\n  ///\n  /// That separateness is what makes it useful: it is independent of whatever\n  /// the text says, so extracted hours can be reconciled against it. Hours the\n  /// text attributes to nothing are the difference, and that difference is a\n  /// fact worth showing rather than an error to hide.\n  workingHours Decimal @default(0) @db.Decimal(6, 2)\n\n  remarks String?\n\n  status WorklogEntryStatus @default(SUBMITTED)\n\n  /// Where this day's text came from.\n  ///\n  /// `MIGRATED` means the collapse built `deliverable` out of the deliverable\n  /// and category LABELS being dropped, because those rows never held the\n  /// instructor's own words. So a migrated day can read \"Live Class Delivery\" —\n  /// phrasing no instructor uses — and that text then feeds extraction, and the\n  /// insight echoes the taxonomy this whole project removed.\n  ///\n  /// Nothing about that is broken. It must simply not be invisible: without this\n  /// column, somebody asks in six months why an instructor apparently wrote\n  /// something they would never write, and there is no answer in the data.\n  ///\n  /// Excluded from the canonical context deliberately. It describes PROVENANCE,\n  /// not content, and a fact about where text came from must not be able to\n  /// change a hash about what the text says.\n  source WorklogEntrySource @default(NATIVE)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  /// One row per instructor per day, enforced by the database rather than by a\n  /// writer remembering to check.\n  @@unique([instructorId, logDate])\n  /// A manager's period view reads by date across instructors.\n  @@index([logDate])\n  @@index([universityId, logDate])\n}\n\n/// What the model made of one day's text, parsed once and reused.\n///\n/// ── Why a table and not a step ────────────────────────────────────────────\n/// Extraction is per DAY, and a week contains seven of them. Without this,\n/// opening a week re-parses seven days that were already parsed when the\n/// instructor opened each of them, and opening the month re-parses thirty.\n///\n/// `sourceHash` is the day's own canonical context. Because a day's context is a\n/// subset of its week's and its month's, one edit moves all three hashes and\n/// invalidates all three — no cascade code, which is the point.\nmodel DayExtraction {\n  id String @id @default(cuid())\n\n  instructorId String\n  instructor   Instructor @relation(fields: [instructorId], references: [id], onDelete: Cascade)\n\n  logDate DateTime @db.Date\n\n  /// SHA-256 over this day's canonical context, prompt version and model id.\n  sourceHash String @db.Char(64)\n\n  /// The exact canonical JSON that was parsed. Frozen; see `AiInsightCache`.\n  rawContext Json\n\n  /// `[{ label, sessions, hours }]`. `sessions` and `hours` are null wherever\n  /// the text did not state them — null is the correct answer to silence, and a\n  /// guess never is.\n  items Json @default(\"[]\")\n\n  /// The day's hours the text attributed to no activity.\n  ///\n  /// `workingHours` minus the extracted hours. Commonly the whole day, when\n  /// somebody wrote what they did without saying how long each part took. Shown\n  /// rather than hidden: without it the group hours look as though they should\n  /// add up to the total, and somebody eventually tries to reconcile them.\n  unallocatedHours Decimal @default(0) @db.Decimal(6, 2)\n\n  status DayExtractionStatus @default(READY)\n\n  promptVersion String\n  modelId       String\n\n  generatedAt DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  @@unique([instructorId, logDate])\n}\n\nenum DayExtractionStatus {\n  READY\n  FAILED\n}\n\nenum WorklogEntrySource {\n  /// Written through the form by the instructor.\n  NATIVE\n  /// Reconstructed by the collapse from the previous system's taxonomy.\n  MIGRATED\n}\n\nenum WorklogEntryStatus {\n  DRAFT\n  SUBMITTED\n  APPROVED\n}\n\n/// The categories and deliverables that were dropped, keyed by the row they came\n/// from.\n///\n/// A recovery path and nothing else. Application code must never read this — if\n/// something needs one of these values, the removal was incomplete and the fix is\n/// upstream, not a join to here.\nmodel WorklogActivityArchive {\n  id String @id @default(cuid())\n\n  /// The `ActivityLog.id` this came from. Not a foreign key: the row it names is\n  /// dropped, and an archive that cascades with its source is not an archive.\n  activityLogId String @unique\n\n  instructorId String\n  workDate     DateTime @db.Date\n\n  activityTypeCode   String?\n  activityTypeLabel  String?\n  deliverableCode    String?\n  deliverableLabel   String?\n  broadCategoryCode  String?\n  broadCategoryLabel String?\n  quantity           Int?\n\n  archivedAt DateTime @default(now())\n\n  @@index([instructorId, workDate])\n}\n"
}

